use std::collections::HashMap;

use crate::solver::SolverProblem;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Task {
    pub template: usize,
    pub group: usize,
    pub weight: u64,
    pub class: u64,
    pub pinned: bool,
}

#[derive(Clone, Debug)]
pub enum Edit {
    Move(usize, usize), Weight(usize, u64), Class(usize, u64), Bind(usize, usize),
    Pin(usize, bool), Quota(usize, u64), Budget(usize, u64), Cap(usize, u64),
}

#[derive(Clone, Default)]
pub struct Query { pub groups: Vec<usize>, pub nodes: Vec<usize>, pub tasks: Vec<usize> }

pub struct Certificate {
    pub totals: [u64; 4],
    pub groups: Vec<[i64; 8]>,
    pub nodes: Vec<[u64; 3]>,
    pub tasks: Vec<[u64; 6]>,
}

pub struct Outcome {
    pub accepted: bool,
    pub revision: u64,
    pub violations: Option<[u64; 4]>,
    pub certificate: Certificate,
}

/// Snapshot of one task as it was in the committed state.
#[derive(Clone, Copy)]
struct TaskSnap {
    template: usize,
    group: usize,
    weight: u64,
    class: u64,
    pinned: bool,
}

/// Inverse operation used to roll a rejected proposal back.
enum Undo {
    Move(usize, usize),
    Weight(usize, u64),
    Class(usize, u64),
    Bind(usize, usize),
    Pin(usize, bool),
    Quota(usize, u64),
    Budget(usize, u64),
    Cap(usize, u64),
}

